(() => {
'use strict';
const {words,categories}=window.BUILDING_DATA;
const house=window.BUILDING_HOUSE;
const byId=Object.fromEntries(words.map(w=>[w.id,w]));
const cats=Object.fromEntries(categories.map(c=>[c.id,c]));
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={
house:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',book:'M12 5C8 2 4 3 2 4v15c3-1 6-1 10 1 4-2 7-2 10-1V4c-3-1-6-2-10 1Zm0 0v15',bookmark:'M6 3h12v18l-6-4-6 4Z',spark:'m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8Z',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',volume:'M11 4 6 8H3v8h3l5 4ZM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14',headphones:'M4 14v-2a8 8 0 0 1 16 0v2M4 12H2v8h5v-8ZM20 12h2v8h-5v-8Z',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M4 6h16M4 12h16M4 18h16',tag:'M3 3h8l10 10-8 8L3 11ZM7 7h.01',cursor:'m5 3 14 10-7 1-3 7Z',arrow:'M4 12h16m-6-6 6 6-6 6',bulb:'M8 16c-5-5-3-13 4-13s9 8 4 13l-1 2H9ZM9 21h6',shuffle:'M3 6h4c5 0 5 12 10 12h4m-4-4 4 4-4 4M3 18h4c2 0 3-2 4-4M15 8c1-1 1-2 3-2h3m-4-4 4 4-4 4',structure:'M4 21V3h16v18M8 3v18M16 3v18M4 8h16M4 15h16',roof:'m2 12 10-9 10 9M5 10v11h14V10M8 10h8',bricks:'M2 5h20v14H2ZM2 12h20M9 5v7M16 12v7',droplet:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13ZM8 15c0 3 2 4 4 4',bolt:'m13 2-9 12h7l-1 8 10-12h-7Z',kitchen:'M3 10h18v11H3ZM8 10v11M16 10v11M7 7V4a3 3 0 0 1 6 0v2M4 15h1M19 15h1',bath:'M3 12h18v4a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4ZM5 12V5a3 3 0 0 1 6 0M6 20v2M18 20v2',sofa:'M4 12V8a3 3 0 0 1 3-3h10a3 3 0 0 1 3 3v4M4 12H2v8h20v-8h-2v5H4ZM5 20v2M19 20v2',window:'M3 3h18v18H3ZM12 3v18M3 12h18',leaf:'M20 3C8 1 1 9 7 16c6 6 16-2 13-13ZM4 21 16 9',tools:'m5 3 4 4-2 3-4-4c-1 5 2 8 7 7l8 8 3-3-8-8c1-5-2-8-7-7ZM4 21l5-5',hammer:'m3 19 9-10 3 3-9 10ZM9 4l3-3 9 8-3 3-4-4-3 3-3-3 4-3Z',ruler:'m2 15 13-13 7 7L9 22ZM6 11l3 3M10 7l3 3M14 3l3 3',wrench:'m5 3 4 4-2 3-4-4c-1 5 2 8 7 7l8 8 3-3-8-8c1-5-2-8-7-7Z',wind:'M3 7h12a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M4 17h5a3 3 0 1 1-3 3',helmet:'M3 17v-3a9 9 0 0 1 18 0v3M2 17h20v4H2ZM12 3v10',bed:'M3 18V7M21 18V7M3 14h18v7M3 9h18M7 9V5h5v4M12 9V5h5v4',close:'M6 6l12 12M18 6 6 18',check:'m5 12 4 4L19 6',slow:'M4 9v6M8 7v10M12 5v14M16 7v10M20 9v6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',cards:'M7 6h14v15H7ZM3 17V2h14',trophy:'M7 3h10v7a5 5 0 0 1-10 0ZM7 5H3v3a4 4 0 0 0 4 4M17 5h4v3a4 4 0 0 1-4 4M12 15v6M8 21h8',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',play:'m8 4 13 8-13 8Z',back:'M20 12H4m6-6-6 6 6 6',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12 22 2M17 2h5v5',stop:'M6 6h12v12H6Z'};
function icon(name){return `<i aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${iconPaths[name]||iconPaths.house}"/></svg></i>`;}
function icons(root=document){$$('i[data-icon]',root).forEach(el=>{el.setAttribute('aria-hidden','true');el.innerHTML=`<svg viewBox="0 0 24 24"><path d="${iconPaths[el.dataset.icon]||iconPaths.house}"/></svg>`;el.removeAttribute('data-icon');});}
const STORAGE='buildlingo.progress.v1';
const validIds=a=>Array.isArray(a)?a.filter(id=>typeof id==='string'&&byId[id]):[];
let loaded={};try{loaded=JSON.parse(localStorage.getItem(STORAGE)||'{}')||{};}catch{}
const state={saved:new Set(validIds(loaded.saved)),learned:new Set(validIds(loaded.learned)),seen:[...new Set(validIds(loaded.seen))],accent:loaded.accent==='en-GB'?'en-GB':'en-US',sessions:Number.isInteger(loaded.sessions)&&loaded.sessions>=0?loaded.sessions:0};
const ui={view:'explore',selected:'roof',layer:'all',room:'all',labels:false,category:'all',query:'',page:1,sort:'az',unlearned:false,collection:'saved',tour:null,mode:'meaning',scope:'all',count:10,session:null};
let storageWarned=false,toastTimer,utterance=null;
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},3600);}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({saved:[...state.saved],learned:[...state.learned],seen:state.seen,accent:state.accent,sessions:state.sessions}));}catch{if(!storageWarned){toast('Progress cannot be saved in this browser. You can still export a backup.');storageWarned=true;}}updateProgress();}
function updateProgress(){const n=state.learned.size,p=Math.round(n/words.length*100);$('#navCount').textContent=words.length;$('#savedCount').textContent=state.saved.size;$('#learnedCount').textContent=n+' '+(n===1?'word':'words')+' learned';$('#learnedPercent').textContent=p+'%';$('#learnedBar').style.width=p+'%';}
function seen(id){state.seen=state.seen.filter(x=>x!==id);state.seen.push(id);persist();}
function stopAudio(){if('speechSynthesis' in window)window.speechSynthesis.cancel();$$('.is-speaking').forEach(b=>{b.classList.remove('is-speaking');b.removeAttribute('aria-busy');});}
function speak(text,slow=false,button=null){
if(!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window)){toast('Speech audio is unavailable here. Open this site in a browser with speech synthesis support.');return;}
stopAudio();const synth=window.speechSynthesis;
utterance=new window.SpeechSynthesisUtterance(text);utterance.lang=state.accent;utterance.rate=slow?.63:.9;utterance.pitch=1;
const voices=synth.getVoices().filter(v=>v.lang.toLowerCase().startsWith('en'));
const preferred=voices.filter(v=>v.lang.toLowerCase().replace('_','-')===state.accent.toLowerCase());
const choices=preferred.length?preferred:voices;
const voice=choices.find(v=>/natural|premium|enhanced|Google|Samantha|Daniel/i.test(v.name))||choices.find(v=>v.default)||choices[0];if(voice)utterance.voice=voice;
const clear=()=>{if(button){button.classList.remove('is-speaking');button.removeAttribute('aria-busy');}};
utterance.onstart=()=>{if(button){button.classList.add('is-speaking');button.setAttribute('aria-busy','true');}};
utterance.onend=clear;utterance.onerror=e=>{clear();if(!['interrupted','canceled'].includes(e.error))toast('Audio could not play. Check your device’s English voices or try another browser.');};
synth.speak(utterance);if(synth.paused)synth.resume();$('#announcement').textContent='Playing '+text;
}
if('speechSynthesis' in window){window.speechSynthesis.getVoices();window.speechSynthesis.addEventListener('voiceschanged',()=>window.speechSynthesis.getVoices());}
const relations={roof:['rafter','ridge','gutter','soffit'],ceiling:['roof','joist','ceiling-height','insulation'],foundation:['footing','slab','column','rebar'],beam:['column','joist','header','load-bearing-wall'],faucet:['sink','shutoff-valve','washer','p-trap'],sink:['faucet','countertop','p-trap','drain'],toilet:['toilet-tank','flush-valve','fill-valve','toilet-seat'],'toilet-tank':['fill-valve','float','overflow-tube','flush-valve'],'p-trap':['drainpipe','sewer','vent-pipe','cleanout'],window:['window-frame','windowpane','windowsill','double-glazing'],'electrical-panel':['circuit-breaker','fuse','cable','ground-wire'],concrete:['cement','rebar','gravel','sand'],plumbing:['pipe','faucet','drain','plumber'],'casement-window':['hinge','window-frame','windowsill','windowpane'],staircase:['tread','riser','landing','handrail'],bed:['mattress','wardrobe','bedroom','closet'],countertop:['backsplash','cabinet','kitchen-island','sink']};
function related(w){return (relations[w.id]||words.filter(x=>x.category===w.category&&x.id!==w.id).map(x=>x.id)).filter(id=>byId[id]).slice(0,4);}
const tourWords=['foundation','beam','rafter','roof','casement-window','bed','bathtub','toilet','staircase','sofa','faucet','electrical-panel'];
function wordMarkup(w,modal=false){const c=cats[w.category],saved=state.saved.has(w.id),learned=state.learned.has(w.id);return `<div class="word-panel-content">${!modal&&ui.tour!==null?`<div class="tour-indicator">Tour ${ui.tour+1} of ${tourWords.length}<button data-action="tour-next">${ui.tour===tourWords.length-1?'Finish':'Next word →'}</button><button data-action="tour-end" aria-label="End guided tour">×</button></div>`:''}<div class="word-panel-top"><span class="category-tag" style="color:${c.color};background:${c.bg}">${esc(c.name)}</span><button class="icon-button bookmark-button ${saved?'is-saved':''}" data-action="save" data-id="${w.id}" aria-label="${saved?'Unsave':'Save'} ${esc(w.term)}" aria-pressed="${saved}">${icon('bookmark')}</button></div><div class="word-preview">${house.illustration(w)}<span class="preview-corner">THE VISUAL FIELD GUIDE</span></div><h2 class="word-title">${esc(w.term)}</h2><p class="word-pronunciation" aria-label="Common US pronunciation">/${esc(w.ipa)}/</p><div class="audio-controls"><button class="audio-button" data-action="speak" data-id="${w.id}" aria-label="Hear ${esc(w.term)}">${icon('volume')}Listen</button><button class="slow-button" data-action="slow" data-id="${w.id}" aria-label="Hear ${esc(w.term)} slowly">${icon('slow')}Slow</button></div><p class="word-section-label">WHAT IT MEANS</p><p class="word-definition">${esc(w.definition)}</p><p class="word-section-label">IN A SENTENCE</p><div class="example-box"><p>“${esc(w.example)}”</p><button class="icon-button" data-action="example" data-id="${w.id}" aria-label="Listen to the example sentence">${icon('volume')}</button></div>${w.aliases?`<div class="word-aliases"><strong>Also called</strong> ${esc(w.aliases)}</div>`:''}<p class="word-section-label">CONNECTED WORDS</p><div class="related-buttons">${related(w).map(id=>`<button data-action="word" data-id="${id}">${esc(byId[id].term)}</button>`).join('')}</div>${w.note?`<div class="word-note">${esc(w.note)}</div>`:''}${modal&&house.svg.includes(`data-word="${w.id}"`)?`<button class="text-button" style="margin-top:15px" data-action="locate" data-id="${w.id}">Find it in the house ${icon('arrow')}</button>`:''}</div><button class="learn-button ${learned?'learned':''}" data-action="learn" data-id="${w.id}" aria-pressed="${learned}">${icon('check')}${learned?'Learned — click to review again':'Mark as learned'}</button>`;}
function renderWordPanel(){const w=byId[ui.selected];$('#wordPanel').innerHTML=wordMarkup(w);if($('#wordDialog').open)$('#dialogWord').innerHTML=wordMarkup(w,true);}
function showDialog(d){if(d.open)return;if(typeof d.showModal==='function')d.showModal();else d.setAttribute('open','');}
function closeDialog(d){if(typeof d.close==='function')d.close();else d.removeAttribute('open');}
function selectWord(id,{modal=false,scroll=false}={}){if(!byId[id])return;ui.selected=id;seen(id);renderWordPanel();updateSceneSelection();if(modal){$('#dialogWord').innerHTML=wordMarkup(byId[id],true);showDialog($('#wordDialog'));$('#wordDialog').scrollTop=0;}else if(scroll&&window.matchMedia('(max-width:970px)').matches)$('#wordPanel').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'});$('#announcement').textContent=byId[id].term+'. '+byId[id].definition;}
function view(name,{scroll=true}={}){if(!['explore','library','practice','collection'].includes(name))name='explore';if(name!==ui.view)stopAudio();ui.view=name;$$('.page-view').forEach(el=>{el.hidden=el.id!==name+'View';});$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);if(b.dataset.view===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#breadcrumb').textContent={explore:'Explore',library:'Vocabulary library',practice:'Practice studio',collection:'My collection'}[name];if(location.hash!=='#'+name)history.replaceState(null,'','#'+name);if(name==='library')renderLibrary();if(name==='collection')renderCollection();if(name==='practice'&&!ui.session)renderPracticeSetup();$('#sidebar').classList.remove('open');$('#menuButton').setAttribute('aria-expanded','false');if(scroll)window.scrollTo({top:0,behavior:'auto'});}
function layerMatches(w){return ui.layer==='all'||({structure:['structure','roofing','materials'],plumbing:['plumbing','bathroom'],electrical:['electrical'],exterior:['exterior','openings','tools']}[ui.layer]||[]).includes(w.category);}
function renderScene(){const svg=$('#houseSvg');svg.setAttribute('viewBox',house.rooms.find(r=>r.id===ui.room).view);svg.setAttribute('class',(ui.labels?'show-labels ':'')+'house-layer-'+ui.layer);const visiblePins=house.pins.filter(p=>{if(p.layer&&p.layer!==ui.layer)return false;if(ui.room!=='all')return p.room===ui.room;if(ui.layer==='all')return p.main&&!p.layer;return layerMatches(byId[p.id]);});$('#housePins').innerHTML=visiblePins.map(house.pinMarkup).join('');$$('.house-object',svg).forEach(el=>{const overlay=el.closest('[data-overlay]');const activeOverlay=!overlay||overlay.dataset.overlay===ui.layer;const roomActive=ui.room==='all'||el.dataset.room===ui.room||el.dataset.room==='structure';const active=activeOverlay&&layerMatches(byId[el.dataset.word])&&roomActive;el.classList.toggle('dimmed',!active);el.setAttribute('tabindex',active?'0':'-1');if(overlay)el.setAttribute('aria-hidden',String(!activeOverlay));});$$('[data-layer]').forEach(b=>{b.classList.toggle('active',b.dataset.layer===ui.layer);b.setAttribute('aria-pressed',String(b.dataset.layer===ui.layer));});$$('[data-room-choice]').forEach(b=>{b.classList.toggle('active',b.dataset.roomChoice===ui.room);b.setAttribute('aria-pressed',String(b.dataset.roomChoice===ui.room));});$('#labelsButton').setAttribute('aria-pressed',String(ui.labels));$('#houseTooltip').hidden=true;updateSceneSelection();}
function updateSceneSelection(){$$('.house-object,.house-pin').forEach(el=>el.classList.toggle('selected',el.dataset.word===ui.selected));}
function locateWord(id){const obj=$('.house-object[data-word="'+id+'"]');if(!obj){selectWord(id,{modal:true});return;}closeDialog($('#wordDialog'));view('explore');ui.layer=obj.closest('[data-overlay]')?.dataset.overlay||'all';ui.room=house.rooms.some(r=>r.id===obj.dataset.room)?obj.dataset.room:'all';renderScene();selectWord(id,{scroll:true});}
function setCategory(id){ui.category=id;ui.page=1;ui.query='';$('#librarySearch').value='';view('library');}
function categoryCards(){$('#categoryGrid').innerHTML=categories.map(c=>`<button class="category-card" data-category-link="${c.id}" style="--cat-bg:${c.bg};--cat-color:${c.color}">${icon(c.icon)}<span class="category-arrow">↗</span><strong>${esc(c.name)}</strong><small>${words.filter(w=>w.category===c.id).length} words to discover</small></button>`).join('');}
function wordCard(w){const c=cats[w.category],saved=state.saved.has(w.id);return `<article class="vocab-card"><div class="vocab-card-top"><span class="category-tag" style="color:${c.color};background:${c.bg}">${esc(c.name)}</span><button class="icon-button bookmark-button ${saved?'is-saved':''}" data-action="save" data-id="${w.id}" aria-label="${saved?'Unsave':'Save'} ${esc(w.term)}" aria-pressed="${saved}">${icon('bookmark')}</button></div><h3><button data-action="word-modal" data-id="${w.id}">${esc(w.term)}</button>${state.learned.has(w.id)?'<span class="learned-dot" title="Learned" aria-label="Learned"></span>':''}</h3><p>${esc(w.definition)}</p><div class="vocab-card-footer"><button class="mini-audio" data-action="speak" data-id="${w.id}" aria-label="Hear ${esc(w.term)}">${icon('volume')}Listen</button><button class="text-button" data-action="word-modal" data-id="${w.id}">Explore word ${icon('arrow')}</button></div></article>`;}
const normalized=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function matches(w,q){return normalized(w.term+' '+w.definition+' '+w.example+' '+w.aliases+' '+cats[w.category].name).includes(normalized(q));}
function emptyState(title,description,button='Explore the house',action='explore'){return `<div class="empty-state">${icon('book')}<h3>${esc(title)}</h3><p>${esc(description)}</p><button class="primary-button" data-empty-action="${action}">${esc(button)} ${icon('arrow')}</button></div>`;}
function renderLibrary(){const filtered=words.filter(w=>(ui.category==='all'||w.category===ui.category)&&matches(w,ui.query)&&(!ui.unlearned||!state.learned.has(w.id)));filtered.sort((a,b)=>{if(ui.sort==='category')return cats[a.category].name.localeCompare(cats[b.category].name)||a.term.localeCompare(b.term);if(ui.sort==='unlearned')return Number(state.learned.has(a.id))-Number(state.learned.has(b.id))||a.term.localeCompare(b.term);return a.term.localeCompare(b.term)||a.category.localeCompare(b.category);});const pages=Math.max(1,Math.ceil(filtered.length/24));ui.page=Math.min(ui.page,pages);$('#libraryCategories').innerHTML=`<button data-filter="all" class="${ui.category==='all'?'active':''}" aria-pressed="${ui.category==='all'}">All vocabulary <small>${words.length}</small></button>`+categories.map(c=>`<button data-filter="${c.id}" class="${ui.category===c.id?'active':''}" aria-pressed="${ui.category===c.id}">${esc(c.name)}</button>`).join('');$('#resultCount').textContent=filtered.length+' '+(filtered.length===1?'word':'words')+(ui.category==='all'?' across every trade':' in '+cats[ui.category].name.toLowerCase());$('#vocabGrid').innerHTML=filtered.length?filtered.slice((ui.page-1)*24,ui.page*24).map(wordCard).join(''):emptyState('No words found.','Try another search, choose a different category, or reset your filters.','Reset filters','reset-library');let pageNumbers=[1,ui.page-1,ui.page,ui.page+1,pages].filter((n,i,a)=>n>=1&&n<=pages&&a.indexOf(n)===i).sort((a,b)=>a-b);$('#pagination').innerHTML=pages>1?`<button data-page="${ui.page-1}" ${ui.page===1?'disabled':''} aria-label="Previous page">←</button>`+pageNumbers.map((n,i)=>(i&&n-pageNumbers[i-1]>1?'<span>…</span>':'')+`<button data-page="${n}" class="${n===ui.page?'active':''}" ${n===ui.page?'aria-current="page"':''}>${n}</button>`).join('')+`<button data-page="${ui.page+1}" ${ui.page===pages?'disabled':''} aria-label="Next page">→</button>`:'';}
function renderCollection(){const n=state.learned.size;$('#collectionStats').innerHTML=[['bookmark',state.saved.size,'words saved'],['check',n,'words learned'],['eye',state.seen.length,'words explored']].map(([ic,num,label])=>`<div class="collection-stat">${icon(ic)}<div><strong>${num}</strong><span>${label}</span></div></div>`).join('');$$('[data-collection]').forEach(b=>{b.classList.toggle('active',b.dataset.collection===ui.collection);b.setAttribute('aria-pressed',String(b.dataset.collection===ui.collection));});const ids=ui.collection==='saved'?[...state.saved]:ui.collection==='learned'?[...state.learned]:[...state.seen].reverse();const list=ids.map(id=>byId[id]);if(ui.collection!=='seen')list.sort((a,b)=>a.term.localeCompare(b.term));$('#collectionGrid').innerHTML=list.length?list.map(wordCard).join(''):emptyState(ui.collection==='saved'?'Your toolbox is ready.':ui.collection==='learned'?'A foundation starts with one word.':'Your next discovery is waiting.',ui.collection==='saved'?'Tap the bookmark beside a word to keep it here.':ui.collection==='learned'?'Open a word and mark it learned when you feel confident.':'Explore the house to start your collection.');}
function refreshSaved(){renderWordPanel();if(ui.view==='library')renderLibrary();if(ui.view==='collection')renderCollection();}
function shuffle(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];}return r;}
function practicePool(){if(ui.scope==='saved')return words.filter(w=>state.saved.has(w.id));if(ui.scope==='unlearned')return words.filter(w=>!state.learned.has(w.id));if(ui.scope==='all')return words;return words.filter(w=>w.category===ui.scope);}
function renderPracticeSetup(){ui.session=null;$('#practiceContent').innerHTML=`<div class="practice-intro"><div class="practice-settings"><h2>Pick your next challenge.</h2><p>One focused session can make a new word feel familiar.</p><label class="field-label" for="practiceScope">YOUR VOCABULARY</label><select id="practiceScope"><option value="all">Every trade · ${words.length} words</option><option value="saved">My saved words · ${state.saved.size}</option><option value="unlearned">Words to learn · ${words.length-state.learned.size}</option>${categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><label class="field-label">HOW WOULD YOU LIKE TO PRACTICE?</label><div class="mode-choices">${[['meaning','book','Find the word','Match an English definition to the right word.'],['listening','headphones','Listen & recognize','Hear a word and choose what you heard.'],['flashcards','cards','Flip through flashcards','Recall the meaning. Reveal it. Make it stick.']].map(([m,ic,title,desc])=>`<button class="mode-choice ${ui.mode===m?'active':''}" data-mode="${m}" aria-pressed="${ui.mode===m}">${icon(ic)}<div><strong>${title}</strong><small>${desc}</small></div><span class="mode-circle"></span></button>`).join('')}</div><label class="field-label" for="practiceLength">SESSION LENGTH</label><select id="practiceLength"><option value="10">10 words · a quick foundation</option><option value="20">20 words · a deeper dive</option><option value="all">All words in this selection</option></select><button class="primary-button" id="startPracticeButton">Start practicing ${icon('arrow')}</button></div><aside class="practice-note">${icon('spark')}<p class="eyebrow">A LITTLE, OFTEN</p><h2>Recognition becomes confidence.</h2><p>Say the word aloud. Picture where it belongs in the house. Then try using it in a sentence of your own.</p><p>Your learned words and saved collection stay with you on this device.</p><span class="tiny-label">SMALL STEPS. SOLID FOUNDATIONS.</span></aside></div>`;$('#practiceScope').value=ui.scope;$('#practiceLength').value=String(ui.count);}
function startPractice(customPool=null,mode=ui.mode){const pool=customPool||practicePool();if(!pool.length){toast('There are no words in this selection yet. Save some words or choose another category.');return;}if(mode==='listening'&&!('speechSynthesis' in window)){toast('Listening practice needs speech synthesis. Try definition practice or flashcards in this browser.');return;}ui.session={mode,pool:shuffle(pool).slice(0,ui.count==='all'?pool.length:Number(ui.count)),index:0,correct:0,wrong:[],answered:false,choice:null,flipped:false,known:0};renderPracticeQuestion(true);}
function buildQuestion(){const s=ui.session,w=s.pool[s.index];const sameCategory=shuffle(words.filter(x=>x.category===w.category&&x.term!==w.term));const other=shuffle(words.filter(x=>x.term!==w.term&&x.category!==w.category));const choices=[],used=new Set([w.term]);for(const x of [...sameCategory,...other]){if(!used.has(x.term)){choices.push(x);used.add(x.term);}if(choices.length===3)break;}return shuffle([w,...choices]);}
function renderPracticeQuestion(fresh=false){const s=ui.session;if(!s)return;if(s.index>=s.pool.length){renderPracticeResults();return;}const w=s.pool[s.index];if(fresh){s.answered=false;s.choice=null;s.flipped=false;s.options=buildQuestion();seen(w.id);stopAudio();}const top=`<div class="practice-session"><div class="session-top"><button class="text-button" data-action="practice-exit">${icon('back')}End session</button><span>${s.mode==='flashcards'?'FLASHCARDS':s.mode==='listening'?'LISTEN & RECOGNIZE':'FIND THE WORD'} · ${s.index+1} / ${s.pool.length}</span><span>${s.mode==='flashcards'?s.known+' learned':s.correct+' correct'}</span></div><div class="session-progress"><span style="width:${s.index/s.pool.length*100}%"></span></div>`;let body='';if(s.mode==='flashcards')body=`<div class="flash-card"><p class="eyebrow">${esc(cats[w.category].name)}</p><h2>${esc(w.term)}</h2><p class="word-pronunciation">/${esc(w.ipa)}/</p><button class="mini-audio" data-action="speak" data-id="${w.id}">${icon('volume')}Listen to the word</button>${s.flipped?`<p class="flash-definition">${esc(w.definition)}</p><p class="flash-example">“${esc(w.example)}”</p><button class="mini-audio" style="margin-top:12px" data-action="example" data-id="${w.id}">${icon('volume')}Hear the example</button>`:`<p class="flash-hint">Try to explain the meaning in your own words.</p><button class="secondary-button" data-action="flip">${icon('eye')}Reveal meaning</button>`}</div><div class="flash-actions">${s.flipped?`<button class="secondary-button" data-action="flash-review">Review again later</button><button class="primary-button" data-action="flash-know">${icon('check')}I know this word</button>`:'<span style="font-size:10px;color:#98a58c">Press Space to reveal the meaning.</span>'}</div>`;else body=`<div class="quiz-card"><p class="eyebrow">${esc(cats[w.category].name)}</p>${s.mode==='listening'?`<button class="listen-big" data-action="speak" data-id="${w.id}" aria-label="Play the mystery word">${icon('volume')}</button><h2>Which word did you hear?</h2><button class="text-button" style="margin-bottom:15px" data-action="slow" data-id="${w.id}">Play it slowly ${icon('slow')}</button>`:`<h2>${esc(w.definition)}</h2>`}<div class="quiz-options">${s.options.map((option,i)=>`<button class="quiz-option ${s.answered?(option.id===w.id?'correct':option.id===s.choice?'incorrect':''):''}" data-answer="${option.id}" ${s.answered?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(option.term)}</button>`).join('')}</div>${s.answered?`<div class="quiz-feedback" role="status"><strong>${s.choice===w.id?'That’s right. A solid foundation!':'The word is '+esc(w.term)+'. Keep building.'}</strong>“${esc(w.example)}”<br><button class="mini-audio" style="display:inline-flex;margin-top:7px" data-action="example" data-id="${w.id}">${icon('volume')}Hear the example</button></div>`:''}</div><div class="session-bottom"><span>${s.answered?'Try using this word in a sentence.':'Choose a word, or press A, B, C, or D.'}</span>${s.answered?`<button class="primary-button" data-action="practice-next">${s.index===s.pool.length-1?'See results':'Next word'} ${icon('arrow')}</button>`:''}</div>`;$('#practiceContent').innerHTML=top+body+'</div>';if(fresh&&s.mode==='listening')speak(w.term);}
function answer(id){const s=ui.session;if(!s||s.answered||s.mode==='flashcards')return;const w=s.pool[s.index];s.answered=true;s.choice=id;if(id===w.id)s.correct++;else s.wrong.push(w);renderPracticeQuestion();$('.quiz-feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function advanceFlash(known){const s=ui.session;if(!s||!s.flipped)return;const w=s.pool[s.index];if(known){state.learned.add(w.id);s.known++;persist();renderWordPanel();}else s.wrong.push(w);s.index++;renderPracticeQuestion(true);}
function renderPracticeResults(){const s=ui.session;stopAudio();if(!s.finished){state.sessions++;persist();s.finished=true;}const flash=s.mode==='flashcards',num=flash?s.known:s.correct;$('#practiceContent').innerHTML=`<div class="results-card">${icon('trophy')}<p class="eyebrow" style="justify-content:center">ANOTHER LAYER OF CONFIDENCE</p><h2>${num===s.pool.length?'A strong foundation.':'Keep building your English.'}</h2><div class="results-score">${num}<span style="font-size:28px;color:#9bad88"> / ${s.pool.length}</span></div><p>${flash?'words marked learned in this session':'correct answers in this session'}</p><p>${s.wrong.length?'These words could use another look:':'You covered every word in this session. Try another trade next.'}</p>${s.wrong.length?`<div class="review-words">${s.wrong.map(w=>`<button data-action="word-modal" data-id="${w.id}">${esc(w.term)}</button>`).join('')}</div>`:''}<div class="results-actions">${s.wrong.length?`<button class="secondary-button" data-action="practice-review">${icon('cards')}Review these words</button>`:''}<button class="primary-button" data-action="practice-restart">Choose another session ${icon('arrow')}</button></div></div>`;}
function globalSearch(){const input=$('#globalSearch'),q=input.value.trim(),pop=$('#searchPopover');if(!q){pop.hidden=true;return;}const matchesList=words.filter(w=>matches(w,q)).sort((a,b)=>Number(!normalized(a.term).startsWith(normalized(q)))-Number(!normalized(b.term).startsWith(normalized(q)))||a.term.localeCompare(b.term));pop.innerHTML=matchesList.length?matchesList.slice(0,7).map(w=>`<button class="search-result" data-action="word-modal" data-id="${w.id}"><div><strong>${esc(w.term)}</strong><small>${esc(cats[w.category].name)}</small></div>${icon('arrow')}</button>`).join('')+`<button class="search-result" data-action="full-search"><div><strong>See all ${matchesList.length} results</strong><small>Search the full vocabulary library</small></div>${icon('arrow')}</button>`:`<div class="search-empty">No words found. Try “pipe,” “roof,” or “window.”</div>`;pop.hidden=false;}
function fullSearch(){ui.query=$('#globalSearch').value.trim();ui.category='all';ui.page=1;$('#librarySearch').value=ui.query;$('#searchPopover').hidden=true;$('#globalSearch').blur();view('library');}
function toggleSave(id){if(state.saved.has(id)){state.saved.delete(id);toast(byId[id].term+' removed from your collection.');}else{state.saved.add(id);toast(byId[id].term+' saved to your collection.');}persist();refreshSaved();}
function toggleLearn(id){if(state.learned.has(id)){state.learned.delete(id);toast(byId[id].term+' is back in your review list.');}else{state.learned.add(id);toast('Another word learned: '+byId[id].term+'.');}persist();refreshSaved();}
function startTour(){ui.tour=0;ui.room='all';ui.layer='all';view('explore');renderScene();selectWord(tourWords[0],{scroll:true});}
function nextTour(){if(ui.tour===null)return;if(ui.tour>=tourWords.length-1){ui.tour=null;toast('Tour complete. Keep exploring, or try a practice session!');renderWordPanel();return;}ui.tour++;selectWord(tourWords[ui.tour],{scroll:true});}
function exportProgress(){const data={app:'Buildlingo',version:1,exportedAt:new Date().toISOString(),saved:[...state.saved].map(id=>({id,word:byId[id].term})),learned:[...state.learned].map(id=>({id,word:byId[id].term})),recentlyExplored:state.seen.map(id=>({id,word:byId[id].term})),completedSessions:state.sessions};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='buildlingo-progress.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Your progress backup has been downloaded.');}
// One delegated handler keeps dynamically rendered cards and dialogs fully interactive.
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-word][role="button"],a[data-view]');if(!el)return;
if(el.dataset.close){closeDialog($('#'+el.dataset.close));return;}
if(el.dataset.view){view(el.dataset.view);return;}
if(el.dataset.layer){ui.layer=el.dataset.layer;ui.room='all';renderScene();return;}
if(el.dataset.roomChoice){ui.room=el.dataset.roomChoice;ui.layer='all';ui.tour=null;renderScene();const first={all:'roof',living:'sofa',kitchen:'countertop',bathroom:'bathtub',bedroom:'bed',attic:'roof',utility:'water-heater',garden:'lawn'}[ui.room];selectWord(first);return;}
if(el.dataset.word){if(el.classList.contains('dimmed'))return;selectWord(el.dataset.word,{scroll:true});return;}
if(el.dataset.categoryLink){setCategory(el.dataset.categoryLink);return;}
if(el.dataset.filter){ui.category=el.dataset.filter;ui.page=1;renderLibrary();return;}
if(el.dataset.page){ui.page=Number(el.dataset.page);renderLibrary();$('#libraryView').scrollIntoView({block:'start',behavior:'smooth'});return;}
if(el.dataset.collection){ui.collection=el.dataset.collection;renderCollection();return;}
if(el.dataset.mode){ui.mode=el.dataset.mode;$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===ui.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===ui.mode));});return;}
if(el.dataset.answer){answer(el.dataset.answer);return;}
if(el.dataset.emptyAction){if(el.dataset.emptyAction==='reset-library'){ui.query='';ui.category='all';ui.unlearned=false;ui.page=1;$('#librarySearch').value='';$('#unlearnedOnly').checked=false;renderLibrary();}else view(el.dataset.emptyAction);return;}
const id=el.dataset.id,w=byId[id];switch(el.dataset.action){case 'speak':if(w)speak(w.term,false,el);break;case 'slow':if(w)speak(w.term,true,el);break;case 'example':if(w)speak(w.example,false,el);break;case 'save':if(w)toggleSave(id);break;case 'learn':if(w)toggleLearn(id);break;case 'word':selectWord(id,{modal:$('#wordDialog').open});break;case 'word-modal':$('#searchPopover').hidden=true;selectWord(id,{modal:true});break;case 'locate':locateWord(id);break;case 'full-search':fullSearch();break;case 'tour-next':nextTour();break;case 'tour-end':ui.tour=null;renderWordPanel();break;case 'practice-exit':stopAudio();renderPracticeSetup();break;case 'flip':if(ui.session){ui.session.flipped=true;renderPracticeQuestion();}break;case 'flash-know':advanceFlash(true);break;case 'flash-review':advanceFlash(false);break;case 'practice-next':if(ui.session?.answered){ui.session.index++;renderPracticeQuestion(true);}break;case 'practice-review':{const pool=ui.session?.wrong||[];ui.mode='flashcards';startPractice(pool,'flashcards');break;}case 'practice-restart':renderPracticeSetup();break;}
});
$('#houseCanvas').innerHTML=house.svg;
$('#roomButtons').innerHTML=house.rooms.map(r=>`<button class="room-button ${r.id==='all'?'active':''}" data-room-choice="${r.id}" aria-pressed="${r.id==='all'}">${icon(r.icon)}${r.name}</button>`).join('');
const canvas=$('#houseCanvas');
canvas.addEventListener('pointerover',event=>{const el=event.target.closest('.house-object,.house-pin');if(!el||el.classList.contains('dimmed'))return;const rect=$('.house-card').getBoundingClientRect(),tip=$('#houseTooltip');tip.textContent=byId[el.dataset.word].term;tip.hidden=false;const x=event.clientX-rect.left,y=event.clientY-rect.top;tip.style.left=Math.max(8,Math.min(x-30,rect.width-180))+'px';tip.style.top=Math.max(48,y-40)+'px';});
canvas.addEventListener('pointerout',()=>{$('#houseTooltip').hidden=true;});
canvas.addEventListener('keydown',event=>{const el=event.target.closest('.house-object,.house-pin');if(el&&['Enter',' '].includes(event.key)){event.preventDefault();selectWord(el.dataset.word,{scroll:true});}});
$('#labelsButton').addEventListener('click',()=>{ui.labels=!ui.labels;renderScene();});
$('#tourButton').addEventListener('click',startTour);
$('#randomButton').addEventListener('click',()=>{const candidates=words.filter(w=>!state.learned.has(w.id));const pool=candidates.length?candidates:words;selectWord(pool[Math.floor(Math.random()*pool.length)].id);toast('A new word to build on.');});
$('#browseAllButton').addEventListener('click',()=>setCategory('all'));
$('#helpButton').addEventListener('click',()=>showDialog($('#helpDialog')));
$('#progressButton').addEventListener('click',()=>{ui.collection='learned';view('collection');});
$('#menuButton').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menuButton').setAttribute('aria-expanded',String(open));});
$('#globalSearch').addEventListener('input',globalSearch);
$('#globalSearch').addEventListener('focus',globalSearch);
$('#globalSearch').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();fullSearch();}if(event.key==='Escape')$('#searchPopover').hidden=true;if(event.key==='ArrowDown'){event.preventDefault();$('#searchPopover button')?.focus();}});
$('#searchPopover').addEventListener('keydown',event=>{if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();const b=$$('button',$('#searchPopover')),i=b.indexOf(document.activeElement);b[(i+(event.key==='ArrowDown'?1:-1)+b.length)%b.length]?.focus();}if(event.key==='Escape'){$('#searchPopover').hidden=true;$('#globalSearch').focus();}});
document.addEventListener('click',event=>{if(!event.target.closest('.global-search'))$('#searchPopover').hidden=true;if($('#sidebar').classList.contains('open')&&!event.target.closest('#sidebar')&&!event.target.closest('#menuButton')){$('#sidebar').classList.remove('open');$('#menuButton').setAttribute('aria-expanded','false');}});
$('#librarySearch').addEventListener('input',event=>{ui.query=event.target.value.trim();ui.page=1;renderLibrary();});
$('#sortSelect').addEventListener('change',event=>{ui.sort=event.target.value;ui.page=1;renderLibrary();});
$('#unlearnedOnly').addEventListener('change',event=>{ui.unlearned=event.target.checked;ui.page=1;renderLibrary();});
$('#accentSelect').value=state.accent;
$('#accentSelect').addEventListener('change',event=>{state.accent=event.target.value;persist();stopAudio();toast('Preferred voice: '+(state.accent==='en-US'?'US English':'UK English')+'.');});
$('#exportButton').addEventListener('click',exportProgress);
$('#practiceContent').addEventListener('change',event=>{if(event.target.id==='practiceScope')ui.scope=event.target.value;if(event.target.id==='practiceLength')ui.count=event.target.value==='all'?'all':Number(event.target.value);});
$('#practiceContent').addEventListener('click',event=>{if(event.target.closest('#startPracticeButton'))startPractice();});
document.addEventListener('keydown',event=>{const typing=event.target.matches('input,textarea,select,[contenteditable="true"]');if(event.key==='/'&&!typing&&!$('dialog[open]')){event.preventDefault();$('#globalSearch').focus();}if(event.key==='Escape'){$('#searchPopover').hidden=true;$('#sidebar').classList.remove('open');$('#menuButton').setAttribute('aria-expanded','false');stopAudio();}if(!typing&&ui.view==='practice'&&ui.session&&!ui.session.finished&&!$('dialog[open]')){const s=ui.session;if(event.code==='Space'&&s.mode==='flashcards'&&!s.flipped&&!event.target.closest('button')){event.preventDefault();s.flipped=true;renderPracticeQuestion();}if(/^[a-d]$/i.test(event.key)&&s.mode!=='flashcards'&&!s.answered){event.preventDefault();answer(s.options[event.key.toLowerCase().charCodeAt(0)-97].id);}if(event.key==='Enter'&&s.answered&&!event.target.closest('button')){s.index++;renderPracticeQuestion(true);}}});
$$('dialog').forEach(d=>{d.addEventListener('click',event=>{if(event.target!==d)return;const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(d);});d.addEventListener('close',stopAudio);});
window.addEventListener('hashchange',()=>view(location.hash.slice(1)));
window.addEventListener('pagehide',stopAudio);
$('#heroCount').textContent=words.length;$('#libraryTotal').textContent=words.length;
icons();categoryCards();renderScene();updateProgress();renderPracticeSetup();selectWord('roof');view(location.hash.slice(1)||'explore',{scroll:false});
})();
